SELECT SUM(CASE WHEN status = 'captured' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN status IN ('captured', 'failed') THEN 1 ELSE 0 END) AS v FROM payments WHERE created_at_utc >= (TIMESTAMP '2024-07-15 00:00:00' - INTERVAL 6 HOUR) AND created_at_utc < (TIMESTAMP '2024-07-16 00:00:00' - INTERVAL 6 HOUR)
